import{_ as a,o as e,c as d,a2 as o}from"./chunks/framework.DaAAbehN.js";const b=JSON.parse('{"title":"第 13 课：安全与权限管理","description":"","frontmatter":{},"headers":[],"relativePath":"modules/module-4/lesson-13.md","filePath":"modules/module-4/lesson-13.md"}'),r={name:"modules/module-4/lesson-13.md"};function l(i,t,h,s,n,u){return e(),d("div",null,[...t[0]||(t[0]=[o(`<h1 id="第-13-课-安全与权限管理" tabindex="-1">第 13 课：安全与权限管理 <a class="header-anchor" href="#第-13-课-安全与权限管理" aria-label="Permalink to &quot;第 13 课：安全与权限管理&quot;">​</a></h1><blockquote><p>📌 <strong>学习目标</strong>：理解使用 Codex 时的安全风险，学会正确设置权限<br> ⏱️ <strong>预计时长</strong>：15 分钟<br> 🎯 <strong>本节节奏</strong>：讲解为主 + 实操演示</p></blockquote><hr><h2 id="一、为什么要有权限管理" tabindex="-1">一、为什么要有权限管理？ <a class="header-anchor" href="#一、为什么要有权限管理" aria-label="Permalink to &quot;一、为什么要有权限管理？&quot;">​</a></h2><p>Codex 能操作你的文件——读取、修改、删除。这意味着它既有强大的能力，也有潜在的风险。</p><p><strong>权限管理的核心目的</strong>：确保 Codex 只在授权范围内使用，保护你的数据安全。</p><hr><h2 id="二、三种权限模式详解" tabindex="-1">二、三种权限模式详解 <a class="header-anchor" href="#二、三种权限模式详解" aria-label="Permalink to &quot;二、三种权限模式详解&quot;">​</a></h2><h3 id="_1-默认权限-推荐新手" tabindex="-1">1. 默认权限（推荐新手） <a class="header-anchor" href="#_1-默认权限-推荐新手" aria-label="Permalink to &quot;1. 默认权限（推荐新手）&quot;">​</a></h3><p>Codex 在执行任何文件修改前都会征求你的同意。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Codex：我打算在文件夹中创建一个新的子文件夹&quot;images&quot;，并将所有图片文件移入其中。是否允许？</span></span>
<span class="line"><span>你：[允许 / 拒绝]</span></span></code></pre></div><p><strong>适用场景</strong>：</p><ul><li>刚开始使用 Codex</li><li>处理重要文件时</li><li>不确定 Codex 会做什么时</li></ul><h3 id="_2-自动审查-推荐进阶用户" tabindex="-1">2. 自动审查（推荐进阶用户） <a class="header-anchor" href="#_2-自动审查-推荐进阶用户" aria-label="Permalink to &quot;2. 自动审查（推荐进阶用户）&quot;">​</a></h3><p>Codex 可以自动执行操作，但你可以在事后查看和审计。</p><p><strong>适用场景</strong>：</p><ul><li>你已经信任 Codex 的工作方式</li><li>处理大量重复性任务时</li><li>⚠️ 操作重要文件前建议先备份</li></ul><h3 id="_3-完全访问-不推荐" tabindex="-1">3. 完全访问（不推荐） <a class="header-anchor" href="#_3-完全访问-不推荐" aria-label="Permalink to &quot;3. 完全访问（不推荐）&quot;">​</a></h3><p>Codex 拥有对你工作区内文件的完全读写权限。</p><p><strong>适用场景</strong>：</p><ul><li>仅在完全了解风险的情况下启用</li><li>不建议新手使用</li></ul><hr><h2 id="三、安全使用指南" tabindex="-1">三、安全使用指南 <a class="header-anchor" href="#三、安全使用指南" aria-label="Permalink to &quot;三、安全使用指南&quot;">​</a></h2><h3 id="✅-应该做的" tabindex="-1">✅ 应该做的 <a class="header-anchor" href="#✅-应该做的" aria-label="Permalink to &quot;✅ 应该做的&quot;">​</a></h3><table tabindex="0"><thead><tr><th>行为</th><th>说明</th></tr></thead><tbody><tr><td>备份重要文件</td><td>让 Codex 操作重要文件前，先备份</td></tr><tr><td>使用默认权限</td><td>刚开始使用时保持默认权限</td></tr><tr><td>审阅结果</td><td>每次 Codex 完成任务后，检查结果是否正确</td></tr><tr><td>限制工作区</td><td>只让 Codex 访问必要的文件夹</td></tr></tbody></table><h3 id="❌-不应该做的" tabindex="-1">❌ 不应该做的 <a class="header-anchor" href="#❌-不应该做的" aria-label="Permalink to &quot;❌ 不应该做的&quot;">​</a></h3><table tabindex="0"><thead><tr><th>行为</th><th>风险</th></tr></thead><tbody><tr><td>输入密码、银行卡等敏感信息</td><td>可能导致隐私泄露</td></tr><tr><td>给 Codex 完全访问权限</td><td>可能误删重要文件</td></tr><tr><td>不检查 Codex 的输出</td><td>可能接受错误的结果</td></tr><tr><td>让 Codex 操作系统关键目录</td><td>可能影响系统正常运行</td></tr></tbody></table><hr><h2 id="四、实操-设置权限" tabindex="-1">四、实操：设置权限 <a class="header-anchor" href="#四、实操-设置权限" aria-label="Permalink to &quot;四、实操：设置权限&quot;">​</a></h2><ol><li>打开 Codex 的设置界面</li><li>找到&quot;权限管理&quot;或&quot;安全设置&quot;</li><li>选择&quot;默认权限&quot;模式</li><li>尝试让 Codex 执行一个文件操作，观察它如何征求你的同意</li></ol><hr><h2 id="五、本节小结" tabindex="-1">五、本节小结 <a class="header-anchor" href="#五、本节小结" aria-label="Permalink to &quot;五、本节小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>知识点</th><th>核心内容</th></tr></thead><tbody><tr><td>权限管理的目的</td><td>确保 Codex 在授权范围内使用</td></tr><tr><td>三种模式</td><td>默认权限（安全）、自动审查（高效）、完全访问（高风险）</td></tr><tr><td>安全原则</td><td>备份重要文件、限制工作区、审阅结果</td></tr><tr><td>敏感信息</td><td>永远不要在 Codex 中输入密码、银行卡等信息</td></tr></tbody></table><hr><h2 id="六、下一步" tabindex="-1">六、下一步 <a class="header-anchor" href="#六、下一步" aria-label="Permalink to &quot;六、下一步&quot;">​</a></h2><p><a href="./lesson-14.html">→ 第 14 课：Codex 的&quot;技能&quot;</a></p>`,36)])])}const p=a(r,[["render",l]]);export{b as __pageData,p as default};
